/// The block methods the client ports class by class.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Method {
    CanBeReplaced,
    CanSurvive,
    GetCollisionShape,
    GetParticlePos,
    GetShape,
    GetStateForPlacement,
    GetType,
    MayPlaceOn,
    UpdateShape,
    UseItemOn,
    UseWithoutItem,
}

/// Every interface a block class implements, directly or through another.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum BlockInterface {
    ItemLike,
    BonemealableBlock,
    SimpleWaterloggedBlock,
    BucketPickup,
    LiquidBlockContainer,
    Fallable,
    EntityBlock,
    SuspiciousEffectHolder,
    SelectableSlotContainer,
    SideChainPartBlock,
    PlainSignBlock,
    HangingSignBlock,
    Portal,
    BeaconBeamBlock,
    WeatheringCopper,
    ChangeOverTimeBlock,
    GameMasterBlock,
    WorldlyContainerHolder,
    SculkBehaviour,
    CaveVines,
    SegmentableBlock,
}

impl BlockInterface {
    /// Every interface, in the order the registry first reaches them.
    pub const ALL: [Self; 21] = [
        Self::ItemLike,
        Self::BonemealableBlock,
        Self::SimpleWaterloggedBlock,
        Self::BucketPickup,
        Self::LiquidBlockContainer,
        Self::Fallable,
        Self::EntityBlock,
        Self::SuspiciousEffectHolder,
        Self::SelectableSlotContainer,
        Self::SideChainPartBlock,
        Self::PlainSignBlock,
        Self::HangingSignBlock,
        Self::Portal,
        Self::BeaconBeamBlock,
        Self::WeatheringCopper,
        Self::ChangeOverTimeBlock,
        Self::GameMasterBlock,
        Self::WorldlyContainerHolder,
        Self::SculkBehaviour,
        Self::CaveVines,
        Self::SegmentableBlock,
    ];

    /// The interfaces this one extends.
    pub const fn parents(self) -> &'static [Self] {
        match self {
            Self::SimpleWaterloggedBlock => &[Self::BucketPickup, Self::LiquidBlockContainer],
            Self::WeatheringCopper => &[Self::ChangeOverTimeBlock],
            _ => &[],
        }
    }
}
